<?php
/**
 * Block registration.
 *
 * @package StarterPlugin
 */

namespace StarterPlugin;

defined( 'ABSPATH' ) || exit;

/**
 * Registers every block built into build/blocks from blocks/.
 */
final class Blocks {

	/**
	 * Constructor.
	 *
	 * @param string $dir Absolute path to the plugin.
	 */
	public function __construct( private string $dir ) {}

	/**
	 * Hook block registration.
	 */
	public function register(): void {
		add_action( 'init', array( $this, 'register_blocks' ) );
	}

	/**
	 * Register all blocks from the manifest generated by `wp-scripts --blocks-manifest`.
	 */
	public function register_blocks(): void {
		$manifest = $this->dir . '/build/blocks/blocks-manifest.php';
		if ( file_exists( $manifest ) ) {
			wp_register_block_types_from_metadata_collection( $this->dir . '/build/blocks', $manifest );
		}
	}
}
